const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PRIMARY_CHANNEL='00000000-0000-0000-0000-000000000001';let activeChannel=typeof localStorage!=='undefined'?(new URLSearchParams(location.search).get('channel')||localStorage.getItem('lofi-channel')||PRIMARY_CHANNEL):PRIMARY_CHANNEL;
let tab=(['growth','autopilot','channels','creator','dashboard','tracks','review','catalog','miniobs','jobs','settings','operations'].includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'dashboard'),cache={},selectedScene='',busy=false;
const money=x=>'US$ '+Number(x||0).toFixed(2),labels={DRAFT:'Rascunho',REVIEW:'Em revisão',APPROVED:'Aprovada',QUEUED:'Na fila',RUNNING:'Gerando',COMPLETED:'Concluída',FAILED:'Falhou',CANCELLED:'Cancelada',UNCERTAIN:'Custo incerto',PENDING:'Pendente',REJECTED:'Rejeitada'};
const tag=x=>`<span class="tag ${esc(x)}">${esc(labels[x]||x)}</span>`;
function notice(x){$('#notice').textContent=x||''}
async function req(path,opt={}){const r=await fetch('/api'+path,{...opt,headers:{...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...((window.studioCSRF?.()||sessionStorage.getItem('lofi_csrf'))?{'X-CSRF-Token':(window.studioCSRF?.()||sessionStorage.getItem('lofi_csrf'))}:{}),...(opt.headers||{})}});let v;try{v=await r.json()}catch{v={}}if(!r.ok)throw Error(typeof v.detail==='string'?v.detail:Array.isArray(v.detail)&&v.detail.length?v.detail.map(d=>String(d.msg||'').replace(/^Value error, /,'')).join(' · '):'Pedido inválido (HTTP '+r.status+')');return v}
function modal(html){$('#modal-content').innerHTML=html;$('#modal-content').querySelectorAll('button').forEach(b=>b.type='button');$('#modal').showModal()}
const close=()=>$('#modal').close();
async function action(fn,message){if(busy)return;busy=true;try{await fn();close();await refresh();notice(message)}catch(e){alert(e.message)}finally{busy=false}}
async function refresh(){try{const paths=['tracks','dashboard','status','catalog','settings','budget','jobs','miniobs/status','miniobs/scenes','miniobs/visuals','autopilot/status','miniobs/programs','channels','ambient/pilots','youtube/capabilities','youtube/channels'];const values=await Promise.all(paths.map(p=>req('/'+p)));[cache.tracks,cache.overview,cache.ops,cache.catalog,cache.settings,cache.budget,cache.jobs,cache.radio,cache.scenes,cache.visuals,cache.factory,cache.programs,cache.channels,cache.pilots,cache.youtubeCapabilities,cache.youtubeConnections]=values;cache.allTracks=cache.tracks;cache.allCatalog=cache.catalog;cache.allJobs=cache.jobs;scopeChannelData();render()}catch(e){notice(e.message)}}
function go(next){tab=next;history.replaceState(null,'','?view='+encodeURIComponent(next));document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});render()}
function tracksTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Faixa</th><th>Coleção</th><th>Status</th><th>Versões</th><th>Ação</th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.title)}</strong><br><small class="muted">${esc(t.id)} · ${t.bpm} BPM</small></td><td>${esc(t.collection)}</td><td>${tag(t.status)}</td><td>${t.asset_count}</td><td><button class="btn secondary" onclick="openTrack('${t.id}')">Abrir</button></td></tr>`).join('')}</tbody></table></div>`}
function filterTracks(){const q=($('#search').value||'').toLowerCase(),status=$('#filter-status').value;$('#track-table').innerHTML=tracksTable(cache.tracks.filter(t=>(!status||t.status===status)&&(t.title+' '+t.collection).toLowerCase().includes(q)))}
function jobsTable(){return cache.jobs.length?`<div class="table-wrap"><table><tr><th>Faixa / modelo</th><th>Status</th><th>Reserva / reportado</th><th>Resultado</th><th></th></tr>${cache.jobs.map(j=>`<tr><td>${esc(j.title)}<br><small class="muted">${esc(j.model)}</small></td><td>${tag(j.status)}</td><td>${money(j.estimated_cost)} / ${j.actual_cost==null?'não informado':money(j.actual_cost)}</td><td><small>${esc(j.detail)}</small></td><td>${j.status==='QUEUED'?`<button class="btn secondary" onclick="cancelJob('${j.id}')">Cancelar</button>`:''}</td></tr>`).join('')}</table></div>`:'<p class="muted">Nenhum pedido de geração. Crie ou abra uma composição para começar.</p>'}
function render(){if(!cache.tracks)return;renderChannelSelector();if(tab==='creator'&&$('#creator-theme'))return;const {tracks,overview,ops,catalog,settings:s,budget:b,radio:r}=cache;$('#page-title').textContent=({growth:'Crescimento e monetização',channels:'Meus canais',creator:'Criar com IA',autopilot:'Meus programas',dashboard:'Visão geral',tracks:'Music Factory',review:'Revisão de áudio',catalog:'Catálogo aprovado',miniobs:'Mini OBS',jobs:'Fila e histórico',settings:'Configurações',operations:'Infraestrutura'})[tab];$('#mode').textContent=cache.radio?.desired==='live'?(cache.radio.state==='sending'?'Enviando sinal · loop contínuo':'Transmissão solicitada'):(cache.programs||[]).some(b=>String(b.channel_id||PRIMARY_CHANNEL)===activeChannel&&['producing','waiting','queued'].includes(b.state))?'Programa em produção':'Revisão e início manual';let html='';if(tab==='channels')html=channelsPage();if(tab==='growth')html=growthPage();if(tab==='creator')html=creatorPage();if(tab==='autopilot')html=cache.programs?.length?programCards():autopilotPage();
if(tab==='dashboard')html=`<div class="cards"><div class="card"><span class="label">Composições planejadas</span><strong>${tracks.length}</strong></div><div class="card"><span class="label">Áudios reais</span><strong>${tracks.reduce((a,t)=>a+t.asset_count,0)}</strong></div><div class="card"><span class="label">Faixas aprovadas</span><strong>${catalog.length}</strong></div><div class="card"><span class="label">Orçamento reservado</span><strong>${money(b.reserved)}</strong><small>de ${money(b.total_limit)} autorizados</small></div></div><div class="grid2"><div class="panel"><h2>Produção</h2><div class="row"><button class="btn" onclick="go('autopilot')">Esteira automática</button><button class="btn secondary" onclick="go('review')">Revisar áudios</button><button class="btn secondary" onclick="go('miniobs')">Abrir Mini OBS</button></div><h2 style="margin-top:24px">Últimas gerações</h2>${jobsTable()}</div><div class="panel"><h2>Próximas ações</h2><p>${s.key_configured?'✓':'○'} Chave OpenRouter ${s.key_configured?'configurada':'pendente'}</p><p>${s.enabled?'✓':'○'} Piloto ${s.enabled?'habilitado':'aguardando orçamento'}</p><p>${catalog.length?'✓':'○'} Conteúdo aprovado: ${catalog.length} faixas</p><p>Mini OBS: ${esc(r.state)} — ${esc(r.detail)}</p><button class="btn secondary" onclick="go('settings')">Configurar piloto</button></div></div>`;
if(tab==='tracks')html=`<div class="toolbar"><input id="search" placeholder="Buscar título ou coleção" oninput="filterTracks()"><select id="filter-status" onchange="filterTracks()"><option value="">Todos os estados</option><option value="DRAFT">Rascunhos</option><option value="REVIEW">Em revisão</option><option value="APPROVED">Aprovadas</option></select><button class="btn" onclick="trackForm()">+ Composição</button></div><div class="panel" id="track-table">${tracksTable(tracks)}</div>`;
if(tab==='review')html=`<div class="panel"><h2>Ouvir, revisar e documentar direitos</h2><p class="muted">Cada versão tem player e decisão editorial próprios. Somente faixas aprovadas entram nas cenas.</p>${tracksTable(tracks.filter(t=>t.status==='REVIEW'))}</div>`;
if(tab==='catalog')html=`<div class="panel"><h2>Acervo aprovado</h2>${catalog.length?catalog.map(t=>`<div class="asset"><strong>${esc(t.title)}</strong> · ${esc(t.collection)} · ${Math.round(t.duration_seconds)}s<audio controls preload="none" src="/api/assets/${t.asset_id}/audio?variant=${t.approved_variant||'original'}"></audio><button class="btn secondary" onclick="openTrack('${t.id}')">Versões e direitos</button></div>`).join(''):'<p class="muted">O catálogo ficará disponível depois de gerar, ouvir e aprovar a primeira música.</p>'}</div>`;
if(tab==='jobs')html=`<div class="panel"><h2>Pedidos e custos</h2><p class="muted">Sem repetição automática. Falhas podem ter sido cobradas; a reserva é mantida até revisão. Reportado é o custo retornado pela API, não uma conciliação da fatura.</p>${jobsTable()}</div><div class="panel gap"><h2>Auditoria</h2><button class="btn secondary" onclick="showAudit()">Consultar eventos</button></div>`;
if(tab==='settings'&&!cache.factory.audio_only)html=`<div class="grid2"><div class="panel"><h2>Music Factory · piloto controlado</h2><label>Modelo padrão<select id="model">${modelOptions(s.model)}</select></label><label>Chave OpenRouter<input id="api-key" type="password" autocomplete="new-password" placeholder="${s.key_configured?'Configurada — vazio preserva a chave':'sk-or-…'}"></label><p class="muted">A chave será protegida no servidor e não será devolvida pela API.</p><div class="row"><label>Limite diário (USD, dia UTC)<input id="daily" type="number" min="0" max="40" step="0.01" value="${s.daily_limit}"></label><label>Limite total deste piloto (USD)<input id="total" type="number" min="0" max="40" step="0.01" value="${s.total_limit}"></label></div><button class="btn secondary" onclick="$('#daily').value=.40;$('#total').value=1">Preencher sugestão: US$ 0,40/dia · US$ 1 total</button><label><input id="enabled" type="checkbox" ${s.enabled?'checked':''}> Habilitar novas gerações</label><label><input id="confirm-paid" type="checkbox"> Autorizo cobranças dentro destes limites para o piloto</label><p><button class="btn" onclick="saveSettings()">Salvar configuração</button></p><p class="muted">Desativar pausa novos pedidos. Uma chamada já enviada ao provedor pode concluir e ser cobrada.</p></div><div class="panel"><h2>Controle de gastos</h2><p>Reserva conservadora: <strong>${money(b.reserved)}</strong></p><p>Reportado pela API: ${money(b.reported)}</p><p>Cobranças ainda sem confirmação: ${b.unconfirmed}</p><p>Limite total: ${money(s.total_limit)}</p><p class="muted">Máximo configurável nesta versão: US$ 40; o limite atual depende da sua autorização. Nenhum fallback para outro modelo, a esteira automática é configurada na aba Produção automática.</p><h2>Modelos e preços</h2><p>Lyria Clip: US$ 0,04 por trecho de 30 s</p><p>Lyria Pro: US$ 0,08 por música</p><button class="btn secondary" onclick="checkModels()">Verificar catálogo atual</button><div id="models-live"></div></div></div>`;
if(tab==='miniobs')html=cache.programs?.length?programCards():miniObs();
if(tab==='operations')html=`<div class="panel"><h2>Dependências verificadas</h2><table>${Object.entries(ops).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${tag(v)}</td></tr>`).join('')}</table><p class="muted">Este painel verifica conectividade das dependências. Não mede a VPS inteira nem confirma a recepção da transmissão no YouTube.</p></div>`;
if(tab==='settings'&&cache.factory.audio_only)html='<div class="panel"><h2>Configurar produção de áudio</h2><p>Use a chave OpenRouter e o orçamento da primeira etapa.</p><button class="btn" onclick="factoryForm()">Abrir configuração</button></div>';if(tab==='dashboard'&&cache.factory.audio_only)html=cache.programs?.length?programCards():autopilotPage();$('#content').innerHTML=html}
function modelOptions(selected){return [['google/lyria-3-clip-preview','Clip · 30 s · US$ 0,04'],['google/lyria-3-pro-preview','Pro · música · US$ 0,08']].map(([id,text])=>`<option value="${id}" ${id===selected?'selected':''}>${text}</option>`).join('')}
function trackForm(id){const t=cache.tracks.find(t=>t.id===id)||{title:'',collection:'Deep Focus Coding',bpm:74,prompt:''};modal(`<h2>${id?'Editar':'Nova'} composição</h2><label>Título<input id="title" maxlength="120" value="${esc(t.title)}"></label><label>Coleção<select id="collection">${['Deep Focus Coding','Rainy Debugging','Night Shift Coding','Morning Coffee & Code'].map(c=>`<option ${c===t.collection?'selected':''}>${c}</option>`).join('')}</select></label><label>BPM<input id="bpm" type="number" min="40" max="180" value="${t.bpm}"></label><label>Prompt<textarea id="prompt">${esc(t.prompt)}</textarea></label><p><button class="btn" onclick="saveTrack('${id||''}')">Salvar</button></p>`)}
function saveTrack(id){action(()=>req('/tracks'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify({channel_id:activeChannel,title:$('#title').value,collection:$('#collection').value,bpm:Number($('#bpm').value),prompt:$('#prompt').value})}),'Composição salva.')}
function qcMetrics(q){if(!q)return '<p>QC pendente</p>';if(typeof q==='string')q=JSON.parse(q);return `<p>QC ${esc(q.version||'legado')} · ${tag(q.status||'PENDING')} · artístico: ${esc(q.artistic_quality||'not_verified')}</p><p>Duração solicitada: ${q.requested_seconds??'não registrada'} s · real: ${Number(q.duration_s||0).toFixed(2)} s · ${q.sample_rate||'?'} Hz · ${q.channels||'?'} canais</p><p>LUFS: ${q.integrated_lufs??'—'} · True peak: ${q.true_peak_dbtp??'—'} dBTP · sample peak: ${q.sample_peak_dbfs??'—'} dBFS · LRA: ${q.loudness_range_lu??'—'}</p><p>Silêncio: ${Number(q.silence_seconds||0).toFixed(2)} s · samples no limite: ${q.clipped_sample_fraction??'—'} · sequência máxima: ${q.longest_full_scale_run??'—'}</p><ul>${(q.reasons||[]).map(r=>`<li>${esc(r.code)} · ${esc(JSON.stringify(r))}</li>`).join('')}</ul>`}
async function openTrack(id){try{const t=cache.tracks.find(t=>t.id===id),assets=await req('/tracks/'+id+'/assets');modal(`<h2>${esc(t.title)}</h2><p>${esc(t.collection)} · ${tag(t.status)}</p><p>${esc(t.description||'')}</p><button class="btn secondary" onclick="trackCopyForm('${id}')">✨ Descrição da música em inglês</button><label>Prompt<textarea readonly>${esc(t.prompt)}</textarea></label><div class="row gap"><button class="btn secondary" onclick="close();trackForm('${id}')">Editar</button>${t.status==='APPROVED'?`<button class="btn secondary" onclick="revoke('${id}')">Revogar aprovação</button>`:`<button class="btn" onclick="generationForm('${id}')">Gerar versão</button>`}</div><h2 class="gap">Versões e qualidade</h2>${assets.length?assets.map(a=>`<div class="asset"><p>${esc(a.model)} · editorial ${tag(a.editorial_status)} · técnico ${tag(a.technical_status)}</p><h3>Original preservado</h3><audio controls preload="none" src="/api/assets/${a.id}/audio"></audio>${qcMetrics(a.qc)}${a.master_object_key?`<h3>Master</h3><audio controls preload="none" src="/api/assets/${a.id}/audio?variant=master"></audio>${qcMetrics(a.master_qc)}`:''}<p>${esc(a.rights_evidence||a.review_note||'Revisão editorial pendente')}</p><div class="row"><button class="btn secondary" onclick="qcInspect('${a.id}')">Analisar sem alterar aprovações</button><button class="btn secondary" onclick="qcReprocess('${id}','${a.id}')">Reprocessar QC grátis</button><button class="btn secondary" onclick="qcHistory('${a.id}')">Histórico e métricas</button><button class="btn secondary" onclick="editorialReview('${id}','${a.id}')">Solicitar revisão</button>${a.editorial_status!=='REJECTED'?`<button class="btn secondary" onclick="approveForm('${id}','${a.id}',${Boolean(a.master_object_key)})">Ouvir e revisar aprovação</button><button class="btn secondary" onclick="reject('${id}','${a.id}')">Rejeitar</button>`:''}</div></div>`).join(''):'<p>Nenhum áudio preservado nesta faixa. QC não pode ser reprocessado sem o arquivo.</p>'}`)}catch(e){alert(e.message)}}
async function qcReprocess(tid,aid){try{await req('/assets/'+aid+'/qc',{method:'POST',body:JSON.stringify({make_master:true})});await openTrack(tid)}catch(e){alert(e.message)}}
async function qcHistory(aid){try{const h=await req('/assets/'+aid+'/qc/history');modal(`<h2>Histórico QC</h2>${h.map(r=>`<p>${esc(r.created_at)} · ${esc(r.version)}</p>${qcMetrics(r.result.original)}${qcMetrics(r.result.master)}<p>${esc(r.result.mastering_error||'')}</p>`).join('')||'<p>Nenhum reprocessamento.</p>'}`)}catch(e){alert(e.message)}}
async function editorialReview(tid,aid){const reason=prompt('Evidência ou motivo para revisão (mínimo 5 caracteres):');if(!reason)return;try{await req('/assets/'+aid+'/review',{method:'POST',body:JSON.stringify({reason})});await openTrack(tid)}catch(e){alert(e.message)}}

function generationForm(id){if(cache.factory.audio_only){close();go('autopilot');return}modal(`<h2>Gerar uma versão</h2><p>Apenas um pedido. Não haverá tentativa automática em caso de falha.</p><label>Modelo<select id="gen-model">${modelOptions(cache.settings.model)}</select></label><p>Reserva atual: ${money(cache.budget.reserved)} / ${money(cache.settings.total_limit)}</p><p><button class="btn" ${cache.settings.enabled&&cache.settings.key_configured?'':'disabled'} onclick="generate('${id}')">Confirmar preço e enviar</button></p>${cache.settings.enabled?'':'<p class="muted">Habilite o piloto nas Configurações.</p>'}`)}
function generate(id){const model=$('#gen-model').value,cost=model.includes('clip')?.04:.08;if(!confirm(`Autorizar uma geração por ${money(cost)}? Em caso de falha, a cobrança pode permanecer.`))return;action(()=>req('/tracks/'+id+'/generate',{method:'POST',body:JSON.stringify({model,confirm_cost:true})}),'Pedido incluído na fila. Acompanhe em Fila e histórico.')}
function approveForm(tid,aid,hasMaster=false){modal(`<h2>Revisão editorial e comercial</h2><label>Versão<select id="variant" onchange="document.querySelector('#reviewAudio').src='/api/assets/${aid}/audio?variant='+this.value"><option value="original">Original</option>${hasMaster?'<option value="master">Master</option>':''}</select></label><audio id="reviewAudio" controls preload="none" src="/api/assets/${aid}/audio"></audio><label><input id="listened" type="checkbox"> Ouvi integralmente e aprovei a qualidade</label><label>Evidência musical: introdução, melodia, harmonia, evolução, transições, repetição, estilo e encerramento<textarea id="musicalNote"></textarea></label><label><input id="technicalReviewed" type="checkbox"> Revisei os alertas técnicos da versão selecionada</label><label>Justificativa dos alertas técnicos<textarea id="technicalNote"></textarea></label><label><input id="rights" type="checkbox"> Revisei licença e condições para o uso pretendido</label><label>Evidência de direitos (documento, URL, data e versão)<textarea id="evidence"></textarea></label><p><button class="btn" onclick="approve('${tid}','${aid}')">Aprovar e registrar</button></p>`)}
function approve(tid,aid){action(()=>req('/tracks/'+tid+'/approve',{method:'POST',body:JSON.stringify({asset_id:aid,listened_fully:$('#listened').checked,reviewed_rights:$('#rights').checked,evidence_reference:$('#evidence').value,variant:$('#variant').value,technical_reviewed:$('#technicalReviewed').checked,technical_review_note:$('#technicalNote').value,musical_review_note:$('#musicalNote').value})}),'Faixa aprovada e auditada.')}

function revoke(id){if(confirm('Retirar a faixa do catálogo e das cenas aprovadas?'))action(()=>req('/tracks/'+id+'/revoke',{method:'POST'}),'Aprovação revogada.')}
function reject(tid,aid){const reason=prompt('Motivo da rejeição (mínimo 5 caracteres):');if(reason)action(()=>req(`/tracks/${tid}/assets/${aid}/reject`,{method:'POST',body:JSON.stringify({reason})}),'Versão rejeitada.')}
function cancelJob(id){action(()=>req('/jobs/'+id+'/cancel',{method:'POST'}),'Pedido cancelado antes do envio.')}
function saveSettings(){const body={model:$('#model').value,api_key:$('#api-key').value||null,daily_limit:Number($('#daily').value),total_limit:Number($('#total').value),enabled:$('#enabled').checked,confirm_paid_pilot:$('#confirm-paid').checked};action(()=>req('/settings',{method:'PUT',body:JSON.stringify(body)}),'Configurações salvas. Nenhuma geração foi solicitada.')}
async function checkModels(){try{const models=await req('/models');$('#models-live').innerHTML=models.map(m=>`<p>${esc(m.name)} · ${money(m.price)}<br>${m.available&&m.price_verified?'Disponibilidade e preço confirmados':'Não confirmado; geração bloqueada'} · <a target="_blank" rel="noopener" href="${esc(m.source)}">Fonte oficial</a></p>`).join('')}catch(e){alert(e.message)}}
async function showAudit(){try{const events=await req('/audit');modal(`<h2>Últimos eventos</h2><div class="table-wrap"><table>${events.map(e=>`<tr><td>${esc(e.action)}<br><small>${esc(e.entity_id)}</small></td><td>${esc(e.detail)}</td><td>${esc(new Date(e.created_at).toLocaleString())}</td></tr>`).join('')}</table></div>`)}catch(e){alert(e.message)}}
function miniObs(){const r=cache.radio;let scene=cache.scenes.find(s=>s.id===selectedScene)||cache.scenes[0];if(scene)selectedScene=scene.id;const visual=scene?.visual_id;return `<div class="obs-layout"><div class="panel"><h2>Cenas</h2><button class="btn" onclick="sceneForm()">+ Nova cena</button>${cache.scenes.map(s=>`<button class="scene-btn ${scene?.id===s.id?'selected':''}" onclick="selectScene('${s.id}')">${esc(s.name)}<small>${s.track_ids.length} faixas</small></button>`).join('')}<h2 class="gap">Biblioteca visual</h2><button class="btn secondary" onclick="visualForm()">Enviar imagem</button><div class="thumb-grid">${cache.visuals.map(v=>`<img src="/api/miniobs/visuals/${v.id}/image" alt="${esc(v.title)}" title="${esc(v.title)}">`).join('')}</div></div><div class="panel"><div class="row spread"><h2>Programa · 720p / 30 fps</h2>${tag(r.state)}</div>${scene?`<div class="stage" style="background-color:${esc(scene.color)}">${visual?`<img src="/api/miniobs/visuals/${visual}/image" alt="Fundo da cena">`:''}<span>${esc(scene.title)}</span><small>Composição da cena · não é retorno ao vivo</small></div><p>${esc(scene.name)} · volume ${Math.round(scene.volume*100)}%</p><div class="row"><button class="btn secondary" onclick="obsCommand('preview')" ${r.desired==='live'?'disabled':''}>Renderizar prévia de 15 s</button><button class="btn" onclick="liveForm()" ${r.desired==='live'?'disabled':''}>Transmitir teste privado</button><button class="btn danger" onclick="stopObs()">Parar</button></div>${scene.preview_key?`<h2 class="gap">Prévia renderizada na VPS</h2><video controls preload="none" src="/api/miniobs/scenes/${scene.id}/preview"></video><a class="btn secondary" href="/api/miniobs/scenes/${scene.id}/preview" download="preview.mp4">Baixar vídeo</a>`:''}<h2 class="gap">Playlist em ordem</h2><ol>${scene.track_ids.map(id=>`<li>${esc(cache.tracks.find(t=>t.id===id)?.title||id)}</li>`).join('')}</ol>`:'<div class="empty-stage"><h2>Prepare sua primeira cena</h2><p>Gere e aprove uma música, envie um fundo e monte a playlist.</p><button class="btn" onclick="go(\'tracks\')">Abrir Music Factory</button></div>'}<p class="muted">${esc(r.detail)}</p></div><div class="panel"><h2>Transmissor</h2><p>Container: ${r.worker_online?'online':'sem heartbeat'}</p><p>Estado: ${esc(r.state)}</p><p>FPS: ${esc(r.fps||'—')} · velocidade ${esc(r.speed||'—')}</p><p>Reconexões: ${r.reconnections}</p><p>Chave: ${r.stream_key_configured?'configurada':'pendente'}</p><button class="btn secondary" onclick="streamForm()">Configurar YouTube</button><p class="muted">Recepção no YouTube não verificada. Crie um evento privado e confirme o sinal no YouTube Studio.</p><p class="muted">H.264 / AAC · 3 Mbps vídeo + 128 kbps áudio. Projeção nominal: ~1 TB por 30 dias; tráfego total da VPS deve ser acompanhado.</p><p class="muted">Cenas estáticas, sem webcam, captura de tela ou mixagem ao vivo nesta versão.</p></div></div>`}
function selectScene(id){selectedScene=id;render()}
function sceneForm(){if(!cache.catalog.length){alert('Aprove uma música antes de criar uma cena.');return}modal(`<h2>Nova cena</h2><label>Nome<input id="scene-name" maxlength="80" value="Rádio Lo-Fi"></label><label>Título no vídeo<input id="scene-title" maxlength="100" value="Lo-Fi Vibe Coding"></label><label>Imagem<select id="scene-visual"><option value="">Fundo sólido</option>${cache.visuals.map(v=>`<option value="${v.id}">${esc(v.title)}</option>`).join('')}</select></label><label>Cor de fundo<input id="scene-color" type="color" value="#101827"></label><label>Volume<input id="scene-volume" type="range" min="0" max="1" step=".05" value=".8"></label><h2 class="gap">Playlist · ordem de seleção</h2><div id="playlist-select">${cache.catalog.map(t=>`<label><input type="checkbox" name="playlist" value="${t.id}" onchange="playlistOrder(this)">${esc(t.title)}</label>`).join('')}</div><p id="playlist-order" class="muted"></p><button class="btn gap" onclick="saveScene()">Salvar cena</button>`);window.sceneOrder=[]}
function playlistOrder(el){if(el.checked)window.sceneOrder.push(el.value);else window.sceneOrder=window.sceneOrder.filter(id=>id!==el.value);$('#playlist-order').textContent=window.sceneOrder.map(id=>cache.tracks.find(t=>t.id===id).title).join(' → ')}
function saveScene(){action(()=>req('/miniobs/scenes',{method:'POST',body:JSON.stringify({name:$('#scene-name').value,title:$('#scene-title').value,visual_id:$('#scene-visual').value||null,color:$('#scene-color').value,volume:Number($('#scene-volume').value),track_ids:window.sceneOrder})}),'Cena salva.')}
function visualForm(){modal(`<h2>Enviar fundo</h2><label>Título<input id="visual-title" maxlength="120"></label><label>PNG ou JPG · até 8 MB<input id="visual-file" type="file" accept="image/png,image/jpeg"></label><label>Evidência de direitos<textarea id="visual-rights" placeholder="Imagem própria; ou licença, origem, data e versão"></textarea></label><p><button class="btn" onclick="uploadVisual()">Enviar para biblioteca</button></p>`)}
function uploadVisual(){const file=$('#visual-file').files[0];if(!file){alert('Selecione uma imagem.');return}const form=new FormData();form.append('file',file);form.append('title',$('#visual-title').value);form.append('rights_evidence',$('#visual-rights').value);action(()=>req('/miniobs/visuals',{method:'POST',body:form}),'Imagem enviada e evidência registrada.')}
function streamForm(){modal(`<h2>Conexão YouTube RTMPS</h2><p>Copie o servidor e a chave do seu evento privado no YouTube Studio. Não envie a chave no chat.</p><label>Servidor RTMPS (sem chave)<input id="ingest" placeholder="Cole o servidor RTMPS do YouTube" value="${esc(cache.radio.ingest_url||'')}"></label><label>Chave de transmissão<input id="stream-key" type="password" autocomplete="new-password" placeholder="${cache.radio.stream_key_configured?'Vazio preserva a chave':'Chave do evento'}"></label><button class="btn gap" onclick="saveStream()">Salvar conexão</button>`)}
function saveStream(){action(()=>req('/miniobs/settings',{method:'PUT',body:JSON.stringify({ingest_url:$('#ingest').value,stream_key:$('#stream-key').value||null})}),'Conexão salva. Transmissão não iniciada.')}
function obsCommand(cmd,confirmed=false){action(()=>req('/miniobs/'+cmd,{method:'POST',body:JSON.stringify({scene_id:selectedScene,confirm_private_event:confirmed,confirm_approved_content:confirmed})}),cmd==='preview'?'Prévia incluída na fila.':'Teste RTMPS solicitado; confirme o sinal no YouTube Studio.')}
function liveForm(){modal(`<h2>Iniciar teste privado</h2><p>A privacidade é definida no YouTube, não pelo transmissor. Configure o evento como <strong>Privado</strong> antes de continuar.</p><label><input type="checkbox" id="private-confirm"> Confirmei que a chave pertence a um evento PRIVADO</label><label><input type="checkbox" id="content-confirm"> Revisei músicas, imagem e direitos de uso</label><button class="btn gap" onclick="startLive()">Enviar sinal de teste</button>`)}
function startLive(){if(!$('#private-confirm').checked||!$('#content-confirm').checked){alert('Confirme as duas verificações.');return}obsCommand('start',true)}
function stopObs(){action(()=>req('/miniobs/stop',{method:'POST'}),'Parada solicitada ao transmissor.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)go(b.dataset.tab)});setInterval(()=>{if(!$('#modal').open&&!busy&&!$('#content').contains?.(document.activeElement)&&tab!=='settings'&&tab!=='tracks'&&![...document.querySelectorAll('video,audio')].some(m=>(!m.paused||m.currentTime>0)&&!m.ended))refresh()},5000);refresh();
function autopilotPage(){const f=cache.factory,h=Number(f.approved_seconds)/3600,target=Number(f.target_seconds||28800)/3600;return `<div class="cards"><div class="card"><span>Músicas prontas</span><strong>${h.toFixed(2)} / ${target} h</strong></div><div class="card"><span>Faixas produzidas</span><strong>${cache.catalog.length}</strong></div><div class="card"><span>Reserva conservadora</span><strong>${money(f.reserved_usd)}</strong></div><div class="card"><span>Teto desta etapa</span><strong>${money(f.budget_usd)}</strong></div></div><div class="panel gap"><div class="row spread"><h2>Primeira etapa · produzir as músicas</h2>${tag(f.state)}</div><p>${esc(f.detail)}</p><progress value="${Math.min(h,target)}" max="${target}" style="width:100%"></progress><p>1. Configurar a chave OpenRouter e o orçamento. &nbsp; 2. Produzir instrumentais em sequência. &nbsp; 3. Ouvir e revisar cada composição antes de aprovar.</p><p>Meta medida por duração: faixas de até 3 minutos, agrupadas em conjuntos de 60. Dois conjuntos podem somar até 6 horas; músicas adicionais completarão a meta de 8 horas. A parada usa a duração real medida; complementos podem ser necessários. Sem configuração de YouTube nesta etapa. Somente OpenRouter para geração.</p><div class="row"><button class="btn" onclick="factoryForm()" ${f.enabled?'disabled':''}>${f.key_configured?'Ajustar configuração':'Configurar e começar'}</button><button class="btn secondary" onclick="factoryCommand('start')" ${f.enabled||!f.key_configured?'disabled':''}>Retomar produção</button><button class="btn danger" onclick="factoryCommand('pause')" ${!f.enabled?'disabled':''}>Pausar</button><button class="btn secondary" onclick="go('catalog')">Ouvir músicas prontas</button></div><p class="muted">${f.audio_only?'Modo somente áudio: imagens, vídeos e transmissão desativados.':'Modo completo habilitado.'} Configuração é feita uma vez, sem botão por faixa. A primeira geração real ainda precisa passar pela OpenRouter e pelo controle técnico.</p></div><div class="grid2"><div class="panel"><h2>Conjuntos</h2>${f.sets.length?f.sets.map(x=>`<p>${esc(x.collection)} · ${x.tracks} faixas · ${(Number(x.seconds)/3600).toFixed(2)} h reais</p>`).join(''):'<p>Os conjuntos aparecerão quando as primeiras faixas forem produzidas.</p>'}<p class="muted">Repetições, rascunhos e rejeições não contam como horas produzidas.</p></div><div class="panel"><h2>Qualidade e custo</h2><p>US$0,08 por geração Lyria Pro. Faixas de até 3 minutos: pelo menos 160 faixas para 8 horas, cerca de US$12,80 antes de rejeições. Teto total máximo: US$20.</p><p>A produção pausa na meta de 8 horas, no teto financeiro ou em falhas. Rejeições podem reduzir a duração alcançada dentro do orçamento.</p><p class="muted">Quality Gate v3 separa PASS, REVIEW e REJECT e preserva o áudio original. A produção pausa após cada resposta. Qualidade artística e direitos exigem revisão auditiva registrada antes do catálogo.</p></div></div><div class="panel gap"><h2>Pedidos mais recentes</h2><div class="table-wrap"><table><tr><th>Estado</th><th>Reserva</th><th>Detalhe</th></tr>${f.tasks.map(t=>`<tr><td>${tag(t.status)}</td><td>${money(t.reserved_cost)}</td><td>${esc(t.detail)}</td></tr>`).join('')}</table></div></div>`}
function factoryForm(){const f=cache.factory;modal(`<h2>Começar a produção das primeiras 8 horas</h2><p>Você precisa somente da chave API OpenRouter e de créditos na conta. <a href="https://openrouter.ai/keys" target="_blank" rel="noopener">Abrir painel de chaves OpenRouter</a>. Não envie a chave pelo chat.</p><label>Chave OpenRouter<input id="OpenRouter-key" type="password" autocomplete="new-password" placeholder="${f.key_configured?'Deixe vazio para manter a chave OpenRouter':'Cole a chave API OpenRouter'}"></label><label>Orçamento máximo desta etapa · USD<input id="factory-budget" type="number" min=".1" max="20" step=".01" value="${f.budget_usd>0?f.budget_usd:20}"></label><label>Política de uso e aprovação<textarea id="factory-rights">${esc(f.rights_policy||'Autorizo instrumentais gerados com prompts próprios, sem imitação de artistas ou amostras de músicas existentes, usando o modelo Lyria Pro por meio do OpenRouter indicado para uso comercial. Li os termos OpenRouter e as condições do modelo na data da configuração.')}</textarea></label><p><a href="https://openrouter.ai/terms" target="_blank" rel="noopener">Termos OpenRouter</a> · <a href="https://openrouter.ai/google/lyria-3-pro-preview" target="_blank" rel="noopener">Condições do modelo</a></p><label><input id="factory-approval" type="checkbox"> Aceito os controles técnicos e a revisão auditiva obrigatória antes da aprovação editorial.</label><p class="muted">Não é preciso configurar YouTube ou transmissão. A chave OpenRouter será validada antes da geração. Nenhuma transmissão será iniciada.</p><button class="btn gap" onclick="saveFactory()">Salvar e começar a produzir</button>`)}
function saveFactory(){const body={api_key:$('#OpenRouter-key').value||null,rights_policy:$('#factory-rights').value,budget_usd:Number($('#factory-budget').value),accept_automatic_approval:$('#factory-approval').checked,autostart_broadcast:false,private_event_confirmed:false};action(async()=>{await req('/autopilot/settings',{method:'PUT',body:JSON.stringify(body)});await req('/autopilot/start',{method:'POST'})},'Produção sequencial iniciada. Acompanhe aqui e ouça as primeiras músicas no Catálogo.')}
function factoryCommand(cmd){action(()=>req('/autopilot/'+cmd,{method:'POST'}),cmd==='pause'?'Produção pausada. Pedido já enviado será recuperado ao retomar.':'Produção retomada.')}

function programCards(){return episodeSeriesPanel()+ambientPilots()+`<div class="panel"><h2>Seu estúdio lo-fi</h2><p>1. Crie com IA → 2. Ouça e confira o visual → 3. Valide → 4. Inicie a live.</p><p>Para repetir um programa revisado, abra seu player e configure o loop. A transmissão começa somente após sua confirmação.</p><button class="btn" onclick="go('creator')">+ Criar novo programa com IA</button></div>`+(cache.programs||[]).filter(b=>String(b.channel_id||PRIMARY_CHANNEL)===activeChannel).map(b=>`<div class="panel gap"><h2>${esc(b.title||b.id)}</h2><p class="muted">${esc(b.theme||'')}</p><div class="cards"><div class="card"><span>Áudio original disponível</span><strong>${(b.playable_seconds/3600).toFixed(2)} / ${(b.target_seconds/3600).toFixed(0)} h</strong></div><div class="card"><span>Músicas completas</span><strong>${b.tracks.length}</strong></div><div class="card"><span>${b.id.startsWith('LOFI8H')?'Reserva do novo lote incluído':'Reserva do lote'}</span><strong>${money(b.reserved)} / ${money(b.budget)}</strong></div></div><p><strong>Visual:</strong> ${esc(b.visual_title||'Em preparação')}${b.visual_cycle_seconds?` · ciclo de ${Math.round(b.visual_cycle_seconds)} segundos em repetição`:''}.</p><p class="muted">${esc((b.visual_scenes||[]).map(s=>s.title).join(' · '))}</p><p><strong>Validação:</strong> ${b.validated?'Registrada para os arquivos atuais':'Aguardando você conferir áudio e vídeo'}.</p><progress max="${b.target_seconds}" value="${Math.min(b.playable_seconds,b.target_seconds)}" style="width:100%"></progress><p>${esc(({producing:'Produzindo novas composições',waiting:'Concluindo os pedidos em andamento',generated:'Músicas geradas; montando programa',preparing:'Reunindo o lote anterior e o novo; sem novas cobranças de geração',ready:'Áudio e vídeo separados prontos',failed:'Produção interrompida: '+b.detail,budget_limit:'Teto financeiro atingido'})[b.state]||b.state)}</p><div class="row"><button class="btn secondary" onclick="editProgramMetadata('${esc(b.id)}')">Título e descrição</button><a class="btn" href="/program-player.html?batch=${encodeURIComponent(b.id)}&channel=${encodeURIComponent(b.channel_id||PRIMARY_CHANNEL)}" target="_blank">Abrir Mini OBS · validar e transmitir</a>${b.audio_ready?`<a class="btn secondary" href="/api/ambient/programs/${encodeURIComponent(b.id)}/tracklist">Tracklist com timestamps</a><a class="btn secondary" href="/api/miniobs/programs/${encodeURIComponent(b.id)}/audio" download="${esc(b.id)}.mp3">Baixar áudio completo</a>`:''}${b.video_ready?`<a class="btn secondary" href="/api/miniobs/programs/${encodeURIComponent(b.id)}/video" download="${esc(b.id)}-visual.mp4">Baixar vídeo sem som</a>`:''}</div><p class="muted">Áudio e vídeo independentes. O visual é uma ilustração animada em loop. Consulte o Mini OBS para acompanhar o sinal e iniciar ou parar este canal.</p></div>`).join('')}

let creativeDraft=null,planRequestId=null;
function creatorPage(){return `${storyboardEditor()}<details id="legacy-creator"><summary>Textos e produção musical do fluxo atual</summary><div class="panel"><h2>Da ideia ao programa, em um lugar</h2><p>1. Escolha o canal e o tema → 2. Revise os textos em inglês → 3. Gere músicas e vídeo → 4. Valide e inicie o loop contínuo.</p><p class="muted">Você pode escrever em português. A IA prepara o tema, a descrição musical e os textos públicos em inglês, com termos relevantes e sem promessas de alcance.</p><label>Tema e clima<textarea id="creator-theme" rows="3" placeholder="Ex.: biblioteca na chuva… ou deixe vazio para a IA sugerir um tema"></textarea></label><label>Intenção principal<select id="creator-intent"><option value="coding_focus">Foco em programação</option><option value="study_focus">Estudo e concentração</option><option value="reading_focus">Leitura tranquila</option><option value="sleep_relaxation">Relaxamento e descanso</option></select></label><label>Termos observados no YouTube Studio<textarea id="creator-search-signals" rows="2" placeholder="Termos de pesquisa observados, separados por linha (opcional)"></textarea></label><div class="grid2"><label>Duração de músicas inéditas<select id="creator-minutes"><option value="2">Uma música · cerca de 2 minutos</option><option value="30">30 minutos</option><option value="60">1 hora</option><option value="120">2 horas</option><option value="240" selected>4 horas</option></select></label><label>Teto para a produção · USD<input id="creator-budget" type="number" min=".23" max="12" step=".01" value="12"></label></div><p class="muted">Planejamento por IA: reserva de até US$0,02 por pedido. Músicas: US$0,08 por composição; visual reutilizado de um episódio aprovado, sem redesenhar personagens. Novos programas usam transições suaves de áudio; a estimativa inclui o tempo sobreposto e pode exigir uma faixa adicional. A duração final das músicas é medida, sem repetir faixas para completar a meta.</p><button id="creator-plan" class="btn" onclick="makeCreativePlan()">✨ Criar tema e textos em inglês</button><p id="creator-status" role="status"></p><div id="creator-draft"></div><details style="margin-top:24px"><summary>Limite acumulado de gastos · ${money(cache.settings.total_limit)}</summary><p>Já reservado: ${money(cache.budget.reserved)}. Este limite inclui todos os programas; cada novo lote também tem seu próprio teto.</p><label>Novo limite acumulado · USD<input id="creator-global-budget" type="number" max="40" min="0" step=".01" value="${cache.settings.total_limit}"></label><label><input id="creator-budget-confirm" type="checkbox"> Autorizo este limite acumulado.</label><button class="btn secondary" onclick="saveCreatorBudget()">Salvar limite</button></details></div></details>`}
async function makeCreativePlan(){if(!confirm('Autoriza reservar até US$0,02 do orçamento configurado para criar este plano de IA?'))return;const button=$('#creator-plan');button.disabled=true;$('#creator-status').textContent='A IA está preparando seu programa…';try{planRequestId=crypto.randomUUID();creativeDraft=await req('/creator/plan',{method:'POST',body:JSON.stringify({request_id:planRequestId,confirm_cost:true,channel_id:activeChannel,theme:$('#creator-theme').value.trim()||'Invent a fresh original cozy lo-fi setting for this channel with cohesive music and an original animated visual. Choose a distinctive theme for coding, studying or reading.',minutes:Number($('#creator-minutes').value),intent:$('#creator-intent')?.value||'coding_focus',search_signals:($('#creator-search-signals')?.value||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,12)})});showCreativeDraft();$('#creator-status').textContent='Sugestão pronta. Ajuste os textos antes de autorizar a produção.'}catch(e){$('#creator-status').textContent=e.message}finally{button.disabled=false}}
function showCreativeDraft(){const p=creativeDraft.plan;if(p.production_spec){storyboardDraftId=creativeDraft.id;loadStoryboardSpec(p.production_spec);$('#creator-draft').innerHTML='<p>Roteiro avançado recuperado. Confira a linha do tempo acima; nenhuma geração foi iniciada.</p>';return;}if($('#legacy-creator'))$('#legacy-creator').open=true;$('#creator-draft').innerHTML=`<hr><h2>Revise seu programa</h2>${p.research_context?.observed_search_phrases?.length?`<p class="muted">Termos reais observados no YouTube Studio: ${esc(p.research_context.observed_search_phrases.join(', '))}. São sinais de linguagem do público, não volume de busca.</p>`:''}<label>Tema sugerido · inglês<textarea id="creative-theme" rows="2">${esc(p.theme)}</textarea></label><label>Título<input id="creative-title" maxlength="100" value="${esc(p.title)}"></label>${(p.alternative_titles||[]).map((t,i)=>`<button class="btn secondary" onclick="selectAlternativeTitle(${i})">${esc(t)}</button>`).join(' ')}<label>Descrição musical em inglês<textarea id="creative-music-description" rows="3">${esc(p.music_description)}</textarea></label><label>Descrição para o YouTube · inglês<textarea id="creative-description" rows="5">${esc(p.description)}</textarea></label><details><summary>Direção da música e do visual</summary><label>Direção musical<textarea id="creative-music" rows="4">${esc(p.music_brief)}</textarea></label><label>Cena original<textarea id="creative-visual" rows="4">${esc(p.visual_prompt)}</textarea></label></details><label>Visual de um episódio de 1h<select id="creative-episode-source"><option value="">Carregando episódios do canal…</option></select></label><p>Reutilizamos o vídeo original de 1h: mesma personagem, gato, cenário e movimentos. Nenhuma nova imagem ou animação será cobrada. A trilha musical é produzida separadamente.</p><label>Som ambiente sob a música<select id="creative-ambient"><option value="none">Nenhum · só música</option><option value="rain">Chuva suave · gerada localmente</option><option value="fireplace">Lareira · gerada localmente</option></select></label><p class="muted">O som ambiente fica cerca de 26 dB abaixo da música, em canal separado; a versão só com música também é salva.</p><p>Mixagem derivada com transições suaves. A sobreposição é descontada da duração e pode exigir músicas adicionais dentro do teto autorizado; os originais são preservados.</p><p id="creative-episode-status"></p><label><input id="creative-confirm" type="checkbox"> Autorizo gerar ${creativeDraft.minutes} minutos de música com este tema, com o teto indicado acima. A transmissão continuará manual.</label><button id="creative-produce" class="btn gap" onclick="produceCreativePlan()">Gerar trilha e usar visual de 1h</button>`;loadCreatorVisualSources()}
async function produceCreativePlan(){const button=$('#creative-produce');button.disabled=true;try{if(!$('#creative-confirm').checked)throw Error('Marque a autorização de custo antes de começar.');const p={...creativeDraft.plan,theme:$('#creative-theme').value,title:$('#creative-title').value,description:$('#creative-description').value,music_description:$('#creative-music-description').value,music_brief:$('#creative-music').value,visual_prompt:$('#creative-visual').value,ambient_bed:$('#creative-ambient')?.value||'none'};const r=await req('/creator/produce',{method:'POST',body:JSON.stringify({plan_id:creativeDraft.id,plan:p,budget:Number($('#creator-budget').value),visual_source_pilot_id:$('#creative-episode-source').value||null,confirm_cost:true})});$('#creator-status').textContent='Produção autorizada. Acompanhe seu novo programa em Meus programas.';go('autopilot');await refresh()}catch(e){$('#creator-status').textContent=e.message;button.disabled=false}}
let metadataDraft=null,metadataProgram=null;
async function editProgramMetadata(bid){const b=cache.programs.find(x=>x.id===bid),m=await req('/creator/programs/'+encodeURIComponent(bid)+'/metadata');metadataDraft={...m,title:m.title===bid?b.title:m.title,theme:m.theme||b.theme};metadataProgram=bid;showMetadataDialog()}
function showMetadataDialog(){const m=metadataDraft;modal(`<h2>Textos em inglês para a live</h2><button id="metadata-ai" class="btn" onclick="suggestMetadataEnglish()">✨ Sugerir títulos e descrição com IA</button><p id="metadata-status" role="status">Reserva de até US$0,02 por sugestão.</p>${m.research_context?.observed_search_phrases?.length?`<p class="muted">Termos observados no Studio: ${esc(m.research_context.observed_search_phrases.join(', '))}. Não são estimativas de volume.</p>`:''}<div>${(m.alternatives||[]).map((t,i)=>`<button class="btn secondary" onclick="selectMetadataTitle(${i})">${esc(t)}</button>`).join(' ')}</div><label>Intenção do vídeo<select id="metadata-intent"><option value="coding_focus" ${m.intent==='coding_focus'?'selected':''}>Foco em programação</option><option value="study_focus" ${m.intent==='study_focus'?'selected':''}>Estudo</option><option value="reading_focus" ${m.intent==='reading_focus'?'selected':''}>Leitura</option><option value="sleep_relaxation" ${m.intent==='sleep_relaxation'?'selected':''}>Relaxamento</option></select></label><label>Título da live<input id="metadata-title" maxlength="100" value="${esc(m.title)}"></label><label>Tema em inglês<textarea id="metadata-theme">${esc(m.theme)}</textarea></label><label>Descrição musical<textarea id="metadata-music" rows="3">${esc(m.music_description)}</textarea></label><label>Descrição da live<textarea id="metadata-description" rows="6">${esc(m.description)}</textarea></label><p class="muted">Termos sugeridos: ${esc((m.keywords||[]).join(', '))}. Não representam volume de busca medido.</p><p>Salve os textos no portal e copie para o evento no YouTube Studio. A conexão de transmissão envia o áudio e o vídeo.</p><button class="btn" onclick="saveProgramMetadata('${metadataProgram}')">Salvar textos</button><button class="btn secondary" onclick="copyMetadataText()">Copiar para o YouTube</button>`)}
async function suggestMetadataEnglish(){if(!confirm('Autoriza reservar até US$0,02 para esta sugestão de IA?'))return;const button=$('#metadata-ai');button.disabled=true;$('#metadata-status').textContent='Preparando títulos e descrição em inglês…';try{const r=await req('/creator/programs/'+encodeURIComponent(metadataProgram)+'/suggest',{method:'POST',body:JSON.stringify({request_id:crypto.randomUUID(),confirm_cost:true})});const p=r.plan;metadataDraft={...metadataDraft,title:p.title,description:p.description,theme:p.theme,music_description:p.music_description,alternatives:p.alternative_titles,keywords:p.keywords,intent:p.intent,research_context:r.research_context};showMetadataDialog();$('#metadata-status').textContent='Sugestão pronta. Revise e salve para aplicar ao programa.'}catch(e){$('#metadata-status').textContent=e.message;button.disabled=false}}
function selectMetadataTitle(i){$('#metadata-title').value=metadataDraft.alternatives[i]}
function selectAlternativeTitle(i){$('#creative-title').value=creativeDraft.plan.alternative_titles[i]}

async function saveProgramMetadata(bid){await action(()=>req('/creator/programs/'+encodeURIComponent(bid)+'/metadata',{method:'PUT',body:JSON.stringify({title:$('#metadata-title').value,description:$('#metadata-description').value,theme:$('#metadata-theme').value,intent:$('#metadata-intent').value,music_description:$('#metadata-music').value,alternatives:metadataDraft.alternatives||[],keywords:metadataDraft.keywords||[]})}),'Título e descrição salvos no portal.');}

async function copyMetadataText(){try{await navigator.clipboard.writeText($('#metadata-title').value+'\n\n'+$('#metadata-description').value);notice('Textos copiados. Cole no evento do YouTube Studio.')}catch{notice('Selecione os textos e copie para o YouTube Studio.')}}

async function saveCreatorBudget(){try{if(!$('#creator-budget-confirm').checked)throw Error('Marque a autorização do limite de gastos.');const amount=Number($('#creator-global-budget').value);const r=await req('/settings',{method:'PUT',body:JSON.stringify({model:cache.settings.model,enabled:cache.settings.enabled,api_key:null,daily_limit:Math.min(Number(cache.settings.daily_limit),amount),total_limit:amount,confirm_paid_pilot:true})});cache.settings=r;$('#creator-status').textContent='Limite acumulado salvo: '+money(amount)+'. Nenhuma produção foi iniciada.'}catch(e){$('#creator-status').textContent=e.message}}

function renderChannelSelector(){const select=$('#channel-selector');if(!select||!cache.channels)return;if(!cache.channels.some(c=>String(c.id)===activeChannel))activeChannel=PRIMARY_CHANNEL;const signature=JSON.stringify(cache.channels.map(c=>[c.id,c.name]));if(select.dataset?.signature!==signature){select.innerHTML=cache.channels.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');if(select.dataset)select.dataset.signature=signature;}select.value=activeChannel;}
function selectChannel(cid){activeChannel=cid;creativeDraft=null;if(typeof storyboardDraftId!=='undefined'){storyboardDraftId=null;latestStoryboard=null;}if(typeof formAssistDraft!=='undefined'){formAssistDraft=null;formAssistRequest=null;}scopeChannelData();if(typeof localStorage!=='undefined')localStorage.setItem('lofi-channel',cid);$('#content').innerHTML='';go('autopilot');}
function channelsPage(){return `<div class="panel"><h2>Canais independentes</h2><p>Cada canal tem sua própria conexão, seus programas e seu transmissor. O início é manual; a repetição contínua mantém áudio e vídeo em loop. Limite atual: quatro canais transmitindo ao mesmo tempo.</p><button class="btn" onclick="channelForm()">+ Adicionar canal</button></div>`+(cache.channels||[]).map(c=>`<div class="panel gap"><h2>${esc(c.name)}</h2><p>${esc(c.niche)}</p><p>Transmissão: ${esc(c.state)} · ${c.stream_key_configured?'Conexão salva':'Conexão pendente'} · ${c.worker_online?'Transmissor disponível':'Transmissor iniciando'}</p><div class="row"><button class="btn" onclick="selectChannel('${c.id}');go('creator')">Criar programa para este canal</button><button class="btn secondary" onclick="selectChannel('${c.id}')">Ver programas</button><button class="btn secondary" onclick="channelForm('${c.id}')">Editar canal</button><button class="btn secondary" onclick="channelConnection('${c.id}')">Conexão do YouTube</button></div></div>`).join('')}
function channelForm(cid){const c=(cache.channels||[]).find(c=>c.id===cid)||{name:'',niche:'',youtube_url:''};modal(`<h2>${cid?'Editar canal':'Novo canal'}</h2><label>Nome<input id="channel-name" maxlength="100" value="${esc(c.name)}"></label><label>Nicho e público<textarea id="channel-niche" rows="3" placeholder="Ex.: cozy jazzhop for studying and reading">${esc(c.niche)}</textarea></label><label>Endereço do canal no YouTube (opcional)<input id="channel-url" value="${esc(c.youtube_url)}"></label><button class="btn" onclick="saveChannel('${cid||''}')">Salvar canal</button>`)}
async function saveChannel(cid){await action(async()=>{const r=await req('/channels'+(cid?'/'+encodeURIComponent(cid):''),{method:cid?'PUT':'POST',body:JSON.stringify({name:$('#channel-name').value,niche:$('#channel-niche').value,youtube_url:$('#channel-url').value})});if(!cid){activeChannel=r.id;if(typeof localStorage!=='undefined')localStorage.setItem('lofi-channel',activeChannel)}},'Canal salvo. Nenhuma transmissão foi iniciada.');}
function channelConnection(cid){const c=cache.channels.find(c=>c.id===cid);modal(`<h2>Conexão · ${esc(c.name)}</h2><label>Servidor RTMP ou RTMPS<input id="channel-ingest" value="${esc(c.ingest_url)}"></label><label>Chave de transmissão<input id="channel-key" type="password" autocomplete="new-password" placeholder="${c.stream_key_configured?'Vazio preserva a chave atual':'Cole a chave deste canal'}"></label><button class="btn" onclick="saveChannelConnection('${cid}')">Salvar conexão deste canal</button><p>Esta chave pertence apenas a este canal. O início continua manual.</p>`)}
async function saveChannelConnection(cid){await action(()=>req('/channels/'+encodeURIComponent(cid)+'/settings',{method:'PUT',body:JSON.stringify({ingest_url:$('#channel-ingest').value,stream_key:$('#channel-key').value||null})}),'Conexão deste canal salva.');}

function trackCopyForm(tid){const t=cache.tracks.find(t=>t.id===tid);modal(`<h2>Textos da música · inglês</h2><label>Título<input id="track-copy-title" maxlength="100" value="${esc(t.title)}"></label><label>Descrição<textarea id="track-copy-description" rows="5">${esc(t.description)}</textarea></label><button id="track-copy-ai" class="btn" onclick="suggestTrackCopy('${tid}')">✨ Sugerir com IA</button><p id="track-copy-status" role="status">Até US$0,02 por sugestão. A descrição usa a direção musical, sem fingir uma análise do áudio.</p><button class="btn secondary" onclick="saveTrackCopy('${tid}')">Salvar textos</button>`)}
async function suggestTrackCopy(tid){if(!confirm('Autoriza reservar até US$0,02 para esta sugestão de IA?'))return;const b=$('#track-copy-ai');b.disabled=true;$('#track-copy-status').textContent='Escrevendo em inglês…';try{const r=await req('/creator/tracks/'+encodeURIComponent(tid)+'/suggest',{method:'POST',body:JSON.stringify({request_id:crypto.randomUUID(),confirm_cost:true})});$('#track-copy-title').value=r.plan.title;$('#track-copy-description').value=r.plan.music_description;$('#track-copy-status').textContent='Sugestão pronta. Revise antes de salvar.'}catch(e){$('#track-copy-status').textContent=e.message}finally{b.disabled=false}}
async function saveTrackCopy(tid){await action(()=>req('/creator/tracks/'+encodeURIComponent(tid)+'/copy',{method:'PUT',body:JSON.stringify({title:$('#track-copy-title').value,description:$('#track-copy-description').value})}),'Textos da música salvos. O áudio foi preservado.');}

function scopeChannelData(){if(cache.allTracks){cache.tracks=cache.allTracks.filter(t=>String(t.channel_id||PRIMARY_CHANNEL)===activeChannel);const own=new Set(cache.tracks.map(t=>t.id));cache.catalog=(cache.allCatalog||[]).filter(t=>own.has(t.id));cache.jobs=(cache.allJobs||[]).filter(j=>own.has(j.track_id));}cache.radio=(cache.channels||[]).find(c=>String(c.id)===activeChannel)||cache.radio;}

function ambientPilots(){return (cache.pilots||[]).filter(p=>String(p.channel_id)===activeChannel&&!p.plan.series).map(p=>`<div class="panel gap"><h2>Piloto de animação ambiental</h2><p>${esc(p.title)} · ${Math.round(p.report.duration_seconds||p.report.performance?.seconds||60)} segundos · separado dos vídeos da live.</p><video controls preload="none" style="width:100%;max-width:900px" src="/api/ambient/pilots/${encodeURIComponent(p.id)}/video"></video>${p.report.delivery_assets?`<div class="cards">${['thumbnail1','thumbnail2','thumbnail3'].map(k=>`<a href="/api/ambient/pilots/${encodeURIComponent(p.id)}/assets/${k}" target="_blank"><img style="width:100%" alt="Proposta original de thumbnail" src="/api/ambient/pilots/${encodeURIComponent(p.id)}/assets/${k}"></a>`).join('')}</div><div class="row"><a class="btn secondary" href="/api/ambient/pilots/${encodeURIComponent(p.id)}/assets/description">Descrição e tracklist</a><a class="btn secondary" href="/api/ambient/pilots/${encodeURIComponent(p.id)}/assets/report">Relatório técnico</a></div><p>Publicação comercial: revisão de direitos e licença pendente. Aprovar o visual não aprova direitos nem monetização.</p>`:''}<p>${p.status==='approved'?'Aprovação visual registrada.':'Assista à personagem, às mãos, ao gato e à passagem do final para o início antes de aprovar.'}</p><p class="muted">${esc((p.plan.unsupported||[]).join(' · '))}</p><p>${esc((p.report.heuristic_flags||[]).map(x=>'Alerta técnico: '+x).join(' · '))}</p><p>Validado tecnicamente não significa anatomia ou qualidade artística aprovadas. Nenhum vídeo existente foi substituído.</p>${p.status==='approved'?'':`<button class="btn" onclick="approveAmbient('${esc(p.id)}')">Aprovar visual do piloto</button>`}</div>`).join('')}
async function approveAmbient(id){if(!confirm('Você assistiu ao piloto e aprova os movimentos e a continuidade do loop? Isso registra sua avaliação; não inicia uma live nem substitui vídeos.'))return;await action(()=>req('/ambient/pilots/'+encodeURIComponent(id)+'/approve',{method:'POST',body:JSON.stringify({confirm_visual:true})}),'Aprovação registrada. Renderização de uma hora ainda não iniciada.');}

function growthPage(){setTimeout(loadGrowth,0);return `<div class="panel"><h2>Qualificação para monetização</h2><p>Dados da aba Ganhos do YouTube Studio, salvos separadamente por canal. Aprovação depende da análise do YouTube.</p><div id="growth-progress">Carregando…</div><button class="btn" onclick="editMonetization()">Atualizar dados da aba Ganhos</button><p>Entrada inicial: 500 inscritos, 3 envios públicos em 90 dias e 3.000 horas qualificadas em 12 meses ou 3 milhões de visualizações qualificadas de Shorts em 90 dias.</p><p>Receita de anúncios: 1.000 inscritos e 4.000 horas qualificadas em 12 meses ou 10 milhões de visualizações qualificadas de Shorts em 90 dias.</p><p>Lives acima de 12 horas não são arquivadas pelo YouTube. Lives não convertidas em VOD não contam para horas qualificadas. Para essa meta, considere sessões públicas de 4–8 horas e confirme o arquivo no YouTube Studio.</p><a href="https://support.google.com/youtube/answer/13429240?hl=pt-BR" target="_blank" rel="noopener">Requisitos oficiais</a></div><div class="panel gap"><h2>Resultados e experimentos</h2><p>Registre somente dados reais do YouTube Studio. Um experimento deve alterar uma variável de cada vez.</p><div class="row"><button class="btn" onclick="growthSnapshotForm()">Registrar métricas</button><button class="btn secondary" onclick="growthExperimentForm()">Novo experimento</button><button class="btn secondary" onclick="growthProjectionForm()">Faixa histórica</button><button class="btn secondary" onclick="growthReferenceForm()">Registrar referência pública</button><button class="btn secondary" onclick="loadReferenceComparison()">Comparar referências</button></div><div id="growth-history"></div><div id="growth-references"></div></div>`}
let monetizationData={};
async function loadGrowth(){const cid=activeChannel;try{const [m,s,e]=await Promise.all([req('/monetization/'+cid),req('/growth/'+cid+'/snapshots'),req('/growth/'+cid+'/experiments')]);if(cid!==activeChannel||tab!=='growth')return;monetizationData=m.data;if(typeof studioGrowthSummary==='function')studioGrowthSummary(s.snapshots);const fmt=v=>v==null?'Não informado':Number(v).toLocaleString('pt-BR');$('#growth-progress').innerHTML=`<div class="cards"><div class="card"><span>Inscritos</span><strong>${fmt(m.data.subscribers)}</strong></div><div class="card"><span>Horas qualificadas · 12 meses</span><strong>${fmt(m.data.valid_watch_hours_12m)}</strong></div><div class="card"><span>Envios públicos · 90 dias</span><strong>${fmt(m.data.public_uploads_90d)}</strong></div></div><p>Direitos: ${m.data.rights_reviewed?'Marcados como revisados por você':'Revisão pendente'}. Aprovação do YouTube: não verificada.</p>`;$('#growth-history').innerHTML=`<p>${s.snapshots.length} registros de métricas · ${e.experiments.length} experimentos</p>`+s.snapshots.slice(0,8).map(r=>`<p>${esc(r.observed_date)} · ${esc(r.window)} · Impressões ${fmt(r.metrics.impressions)} · CTR ${fmt(r.metrics.ctr_percent)}% · Horas assistidas ${fmt(r.metrics.watch_hours)}</p>`).join('')+e.experiments.slice(0,8).map(r=>`<p>${esc(r.hypothesis)} · ${esc(r.variable)} · ${esc(r.status)}</p>`).join('');}catch(e){notice(e.message)}}
function editMonetization(){const d=monetizationData;modal(`<h2>Dados da aba Ganhos</h2><p>Deixe vazio o que não foi informado pelo YouTube. Horas assistidas gerais podem diferir das horas qualificadas.</p>${[['subscribers','Inscritos'],['valid_watch_hours_12m','Horas qualificadas nos últimos 12 meses'],['public_uploads_90d','Envios públicos nos últimos 90 dias'],['valid_shorts_views_90d','Visualizações qualificadas de Shorts · 90 dias']].map(([k,l])=>`<label>${l}<input id="earn-${k}" type="number" min="0" step="any" value="${d[k]??''}"></label>`).join('')}<label><input id="earn-rights" type="checkbox" ${d.rights_reviewed?'checked':''}> Revisei os direitos e as licenças dos ativos.</label><button class="btn" onclick="saveMonetization()">Salvar neste canal</button>`)}
async function saveMonetization(){const body={...monetizationData};for(const k of ['subscribers','valid_watch_hours_12m','public_uploads_90d','valid_shorts_views_90d'])body[k]=$('#earn-'+k).value===''?null:Number($('#earn-'+k).value);body.rights_reviewed=$('#earn-rights').checked;await action(()=>req('/monetization/'+activeChannel,{method:'PUT',body:JSON.stringify(body)}),'Progresso salvo por canal. Nenhuma aprovação automática foi declarada.');loadGrowth()}
function growthSnapshotForm(){modal(`<h2>Métricas reais do YouTube Studio</h2><label>Intenção principal<select id="gm-intent"><option value="coding_focus">Foco em programação</option><option value="study_focus">Estudo</option><option value="reading_focus">Leitura</option><option value="sleep_relaxation">Relaxamento</option></select></label><label>Formato<select id="gm-format"><option value="long_form">Vídeo longo</option><option value="short">Short</option><option value="live_archive">Arquivo de live</option></select></label><label>Idade do vídeo em dias<input id="gm-age" type="number" min="0"></label><label>Termos de pesquisa mostrados no Studio<textarea id="gm-search-terms" rows="3" placeholder="Um termo por linha; deixe vazio se não houver dados"></textarea></label><label>URL pública do vídeo<input id="gm-url" type="url"></label><label>Data da observação<input id="gm-date" type="date"></label><label>Janela<select id="gm-window"><option>24h</option><option>7d</option><option>28d</option><option>90d</option></select></label><label>Eventos nos minutos 15/30/45<select id="gm-markers"><option value="unknown">Não informado</option><option value="with_markers">Com eventos</option><option value="without_markers">Sem eventos</option></select></label>${[['impressions','Impressões'],['ctr_percent','CTR (%)'],['views','Visualizações'],['average_view_duration_seconds','Duração média (segundos)'],['watch_hours','Horas assistidas'],['returning_viewers','Espectadores recorrentes'],['concurrent_peak','Pico simultâneo'],['retention_15_percent','Retenção no minuto 15 (%)'],['retention_30_percent','Retenção no minuto 30 (%)'],['retention_45_percent','Retenção no minuto 45 (%)']].map(([k,l])=>`<label>${l}<input id="gm-${k}" type="number" min="0" step="any"></label>`).join('')}<p>Deixe vazio se o YouTube ainda não mostrou a métrica.</p><button class="btn" onclick="saveGrowthSnapshot()">Salvar métricas</button>`)}
async function saveGrowthSnapshot(){const b={video_url:$('#gm-url').value,observed_date:$('#gm-date').value,window:$('#gm-window').value,event_markers:$('#gm-markers').value,intent:$('#gm-intent').value,content_format:$('#gm-format').value,video_age_days:$('#gm-age').value===''?null:Number($('#gm-age').value),search_terms:$('#gm-search-terms').value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,12)};for(const k of ['impressions','ctr_percent','views','average_view_duration_seconds','watch_hours','returning_viewers','concurrent_peak','retention_15_percent','retention_30_percent','retention_45_percent'])b[k]=$('#gm-'+k).value===''?null:Number($('#gm-'+k).value);await action(()=>req('/growth/'+activeChannel+'/snapshots',{method:'POST',body:JSON.stringify(b)}),'Métricas registradas.');loadGrowth()}
function growthExperimentForm(){modal(`<h2>Experimento com uma variável</h2><label>Hipótese<textarea id="ge-hypothesis"></textarea></label><label>Variável<select id="ge-variable"><option value="title">Título</option><option value="thumbnail">Thumbnail</option><option value="visual">Visual</option><option value="music_selection">Seleção musical</option><option value="event_markers">Eventos nos minutos 15/30/45</option><option value="schedule">Horário</option></select></label><button class="btn" onclick="saveGrowthExperiment()">Salvar experimento</button>`)}
async function saveGrowthExperiment(){await action(()=>req('/growth/'+activeChannel+'/experiments',{method:'POST',body:JSON.stringify({hypothesis:$('#ge-hypothesis').value,variable:$('#ge-variable').value})}),'Experimento registrado.');loadGrowth()}

async function loadCreatorVisualSources(){const cid=activeChannel,pid=creativeDraft?.id;try{const rows=await req('/live-presentation/'+safeId(cid)+'/sources');if(cid!==activeChannel||pid!==creativeDraft?.id||!$('#creative-episode-source'))return;$('#creative-episode-source').innerHTML='<option value="">Escolha um episódio de 1 hora</option>'+rows.map(r=>`<option value="${esc(r.pilot_id)}">${esc(r.title)}</option>`).join('');$('#creative-episode-status').textContent=rows.length?'A escolha preserva exatamente o visual existente; a aprovação do novo programa será separada.':'Nenhum vídeo de 1h publicado disponível neste canal. Nenhuma geração iniciada.';}catch(e){if($('#creative-episode-status'))$('#creative-episode-status').textContent=e.message;}}

async function qcInspect(aid){try{const result=await req('/assets/'+aid+'/qc/inspect',{method:'POST'});modal(`<h2>Diagnóstico do original</h2><p>Arquivo e aprovações preservados. Nenhuma geração paga.</p>${qcMetrics(result.original)}`)}catch(e){alert(e.message)}}

function growthProjectionForm(){modal(`<h2>Faixa histórica do canal</h2><p>Compara vídeos próprios da mesma intenção e formato, com idade e janela semelhantes. Exige pelo menos cinco vídeos; não prevê o algoritmo.</p><label>Intenção<select id="gp-intent"><option value="coding_focus">Foco em programação</option><option value="study_focus">Estudo</option><option value="reading_focus">Leitura</option><option value="sleep_relaxation">Relaxamento</option></select></label><label>Formato<select id="gp-format"><option value="long_form">Vídeo longo</option><option value="short">Short</option><option value="live_archive">Arquivo de live</option></select></label><label>Janela<select id="gp-window"><option>24h</option><option>7d</option><option>28d</option><option>90d</option></select></label><button class="btn" onclick="showGrowthProjection()">Calcular faixa</button><div id="gp-result"></div>`)}
async function showGrowthProjection(){const q=new URLSearchParams({intent:$('#gp-intent').value,content_format:$('#gp-format').value,window:$('#gp-window').value});const r=await req('/growth/'+activeChannel+'/projections?'+q);$('#gp-result').innerHTML=`<p>${esc(r.message||r.method)} · ${r.sample_videos} vídeos comparáveis</p>`+Object.entries(r.metrics||{}).map(([k,v])=>`<p>${esc(k)}: P25 ${Number(v.p25).toLocaleString('pt-BR',{maximumFractionDigits:1})} · mediana ${Number(v.median).toLocaleString('pt-BR',{maximumFractionDigits:1})} · P75 ${Number(v.p75).toLocaleString('pt-BR',{maximumFractionDigits:1})} (${v.observed_videos} vídeos)</p>`).join('')+`<small>${esc(r.interpretation_note||'')}</small>`}
function growthReferenceForm(){modal(`<h2>Registrar observação pública</h2><p>Use somente dados visíveis publicamente. Para velocidade, registre o mesmo vídeo em pelo menos duas datas.</p><label>Canal de referência<input id="gr-name" maxlength="160"></label><label>URL do canal<input id="gr-channel" type="url"></label><label>Tipo<select id="gr-type"><option value="direct">Concorrente direto</option><option value="adjacent">Canal adjacente</option><option value="packaging">Referência de embalagem</option></select></label><label>URL do vídeo<input id="gr-video" type="url"></label><label>Título observado<input id="gr-title" maxlength="300"></label><label>Data de publicação (se disponível)<input id="gr-published" type="date"></label><label>Data desta observação<input id="gr-date" type="date"></label><label>Visualizações públicas<input id="gr-views" type="number" min="0"></label><label>Intenção comparável<input id="gr-intent" maxlength="100" value="coding_focus"></label><button class="btn" onclick="saveGrowthReference()">Salvar observação</button>`)}
async function saveGrowthReference(){const body={reference_name:$('#gr-name').value,reference_url:$('#gr-channel').value,reference_type:$('#gr-type').value,video_url:$('#gr-video').value,video_title:$('#gr-title').value,published_date:$('#gr-published').value||null,observed_date:$('#gr-date').value,public_views:$('#gr-views').value===''?null:Number($('#gr-views').value),intent:$('#gr-intent').value};await action(()=>req('/growth/'+activeChannel+'/references',{method:'POST',body:JSON.stringify(body)}),'Observação pública registrada. Registre novamente em outra data para calcular velocidade aproximada.');loadGrowth()}
async function loadReferenceComparison(){try{const r=await req('/growth/'+activeChannel+'/reference-comparison');$('#growth-references').innerHTML='<h3>Velocidade aproximada das referências</h3>'+r.comparisons.map(x=>`<p>${esc(x.reference_name)} · ${esc(x.video_title)} · ${Number(x.views_per_day_approx).toFixed(1)} visualizações/dia aproximadas${x.outlier_ratio_within_channel?` · ${Number(x.outlier_ratio_within_channel).toFixed(1)}× mediana deste canal`:''}</p>`).join('')+`<small>${esc(r.note)}</small>`}catch(e){notice(e.message)}}
